auth.probe_js:
// Forem states it itself, twice. body[data-user-status] is rendered by the layout
// (app/views/layouts/application.html.erb) and Forem's own checkUserLoggedIn() reads exactly that
// attribute; the whole record is JSON in body.dataset.user (utilities/userData.js).
// Cookies are not evidence: remember_user_token and the Rails session cookie are HttpOnly.
const b = document.body;
const status = b ? b.getAttribute('data-user-status') : null;
let as;
try {
  const d = b && b.dataset ? b.dataset.user : null;
  if (d) { const j = JSON.parse(d); as = j.username || j.name || undefined; }
} catch (e) { /* a half-written dataset is not a verdict */ }
if (as) return {signed_in:true, as};
if (status === 'logged-in') return {signed_in:true, why:'body[data-user-status]=logged-in; body.dataset.user not populated yet'};
// TRAP, same shape as reddit's me.json: /async_info/base_data answers HTTP 200 when signed OUT too
// — the body is then {broadcast, param, token} with NO `user` key at all. Check the FIELD, not the
// status. Second trap: `user` is a JSON *string* (user_data does .to_json), so it needs a 2nd parse.
try {
  const r = await fetch('/async_info/base_data', {credentials:'include', headers:{accept:'application/json'}});
  const j = await r.json();
  if (!j || !j.user) return {signed_in:false, why:'base_data carries no user field'};
  const u = typeof j.user === 'string' ? JSON.parse(j.user) : j.user;
  return {signed_in:true, as: u.username || u.name || undefined};
} catch (e) { return {signed_in:false, why:'no body user data; base_data failed: ' + e.message}; }
